const SYR_URL='https://77.42.87.116.sslip.io';
const SYR_PTS=[[52.23,21.01,3],[52.21,20.98,2],[52.25,21.05,3],[52.19,21.02,1],[52.2,21.08,0],[52.17,20.95,0],[52.26,20.97,2],[52.215,21.04,3],[52.18,21.06,1],[52.24,20.93,1],[52.205,21.0,3],[52.165,21.03,0]];
function syrena(){const mine=S.v4.syrena;shell('📢 Syrena 26',`<div class="alert b">🔊<div><b>Czy słychać syrenę tam, gdzie mieszkasz?</b> Syrena 26 to obywatelski test słyszalności syren alarmowych. Podczas próby zaznaczasz, czy i jak dobrze słyszysz syrenę – z mapy zgłoszeń gmina i RCB widzą „białe plamy”, gdzie trzeba dołożyć syrenę lub polegać na alertach w telefonie.</div></div>
 <div class="card"><h3>📅 Najbliższa próba syren</h3><div class="row"><span>Ostatni test</span><b>12.10.2026, 10:30</b></div><div class="row"><span>Następny test (DEMO)</span><b>12.01.2027, 10:30</b></div><div class="row"><span>Przypomnienie</span><b>${S.v4.alerts.syrena?'🔔 włączone':'🔕 wyłączone'}</b></div><button class="btn" onclick="syrReport()">🔊 Zgłoś: słyszę / nie słyszę</button><a class="btn ghost" href="${SYR_URL}" target="_blank" rel="noopener">Otwórz aplikację Syrena 26 ↗</a></div>
 <div class="card"><h3>🗺️ Mapa słyszalności – test 12.10 (DEMO)</h3><div id="smap" style="height:240px;border-radius:12px"></div><div class="legend"><span><i style="background:#14804a"></i>wyraźnie</span><span><i style="background:#9bc53d"></i>dobrze</span><span><i style="background:#c77700"></i>słabo</span><span><i style="background:#dc143c"></i>nie słychać</span></div><p class="muted">Dane przykładowe. W wersji docelowej mapa pobiera zagregowane, zanonimizowane wyniki z serwera Syrena 26 – bez lokalizacji pojedynczych osób, siatka 500 m.</p></div>
 ${mine.length?card('Twoje zgłoszenia',mine.map(m=>`<div class="row"><span>${m.t}<br><span class="muted">${m.where}</span></span><b>${m.lvl}</b></div>`).join('')):''}
 <div class="card"><h3>Dlaczego to ważne</h3><p class="muted">Syreny projektowano dla miast sprzed dekad: dziś szczelne okna, hałas ruchu i nowe osiedla tworzą miejsca, gdzie alarmu nie słychać. Twoje zgłoszenie trafia do gminy jako dane do planu ostrzegania – a Ty dostajesz pewność, że alarm dotrze do Ciebie także przez telefon.</p></div>`,{tab:'security'});
 setTimeout(()=>{if(!window.L||!$('#smap'))return;const m=L.map('smap',{zoomControl:false}).setView([52.21,21.01],11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(m);const C=['#dc143c','#c77700','#9bc53d','#14804a'];SYR_PTS.concat(mine.filter(x=>x.lat).map(x=>[x.lat,x.lng,x.v])).forEach(([a,b,v])=>L.circle([a,b],{radius:900,color:C[v],fillColor:C[v],fillOpacity:.45,weight:0}).addTo(m).bindTooltip(['nie słychać','słabo','dobrze','wyraźnie'][v]))},60)}
function syrReport(){const m=modal(`<h3>🔊 Jak słyszysz syrenę?</h3><p class="muted">Odpowiedz w trakcie lub tuż po próbie.</p>${['Wyraźnie – także przy zamkniętych oknach','Dobrze – przy otwartym oknie / na zewnątrz','Słabo – ledwo słychać','Nie słychać wcale'].map((x,i)=>`<label class="chk"><input type="radio" name="sl" value="${3-i}" ${i?'':'checked'}> ${x}</label>`).join('')}<label>Gdzie byłeś/aś</label><select id="sw"><option>W domu, okna zamknięte</option><option>W domu, okna otwarte</option><option>Na zewnątrz</option><option>W pracy / szkole</option><option>W samochodzie</option></select><label class="chk"><input type="checkbox" id="sgps" checked> Dołącz lokalizację z dokładnością do 500 m</label><button class="btn" id="sok">Wyślij do Syrena 26</button><button class="btn ghost" onclick="closeModal()">Anuluj</button>`);
 m.querySelector('#sok').onclick=()=>{const v=+m.querySelector('[name=sl]:checked').value,w=m.querySelector('#sw').value,useGps=m.querySelector('#sgps').checked;const rec=(lat,lng)=>{S.v4.syrena.push({t:new Date().toLocaleString('pl-PL'),where:w,lvl:['nie słychać','słabo','dobrze','wyraźnie'][v],v,lat,lng});save();closeModal();syrena();toast('Dziękujemy! Zgłoszenie trafiło do Syrena 26 (DEMO)')};
  if(useGps&&navigator.geolocation)navigator.geolocation.getCurrentPosition(p=>rec(Math.round(p.coords.latitude*200)/200,Math.round(p.coords.longitude*200)/200),()=>rec(52.2+Math.random()*.05,21+Math.random()*.05),{timeout:4000});else rec(52.2+Math.random()*.05,21+Math.random()*.05)}}

