let lawc=[];
function lawai(){if(!lawc.length)lawc=[{r:'a',t:'Jestem doradcą prawnym AI (prototyp). Wyjaśnię przepisy i wskażę ich źródło. Nie zastępuję prawnika – w sprawach o dużej wadze umówię Cię na nieodpłatną poradę z człowiekiem.'}];
 shell('🤖 Doradca prawny AI',`<div class="chat" id="cl"></div><div class="chips">${['Sklep nie chce przyjąć reklamacji','Właściciel nie oddaje kaucji','Dostałem wypowiedzenie','Czy muszę przyjąć mandat?'].map(c=>`<button class="chip" onclick="askLaw('${c}')">${c}</button>`).join('')}</div><p class="muted" style="font-size:.75em">Silnik: ${S.llm.url?esc(S.llm.model):'baza odpowiedzi offline'}. Każda odpowiedź podaje podstawę prawną. Sprawdź aktualny tekst przepisu w <a href="#/acts">bazie aktów</a>.</p>`,{tab:'more'});
 app.insertBefore(Object.assign(document.createElement('div'),{className:'composer',innerHTML:'<input id="ql" placeholder="Opisz swoją sytuację…"><button class="mic" style="background:var(--blue)" onclick="askLaw($(\'#ql\').value)">➤</button>'}),app.querySelector('.nav'));$('#ql').onkeydown=e=>{if(e.key=='Enter')askLaw(e.target.value)};drawLaw()}
function drawLaw(){const c=$('#cl');if(!c)return;c.innerHTML=lawc.map(m=>`<div class="msg ${m.r}">${m.h||esc(m.t)}</div>`).join('');const sc=app.querySelector('.scroll');sc.scrollTop=sc.scrollHeight}
async function askLaw(q){q=(q||'').trim();if(!q)return;if($('#ql'))$('#ql').value='';lawc.push({r:'u',t:q});drawLaw();const hit=LAWQA.find(([re])=>re.test(q.toLowerCase()));let ans=hit?hit[1]:'Nie mam w bazie gotowej odpowiedzi na to pytanie. Opisz, proszę: kto, co, kiedy i czy masz pismo od drugiej strony lub urzędu.',src=hit?hit[2]:[];
 if(S.llm.url||(window.aiOn&&aiOn())){try{ans=await llm('Jesteś doradcą prawnym w aplikacji publicznej (prototyp). Odpowiadaj po polsku, krótko, wskazując podstawę prawną (akt, artykuł). Oddziel to, co wynika wprost z przepisu, od interpretacji. Jeśli nie masz pewności, powiedz to. Zawsze przypomnij o nieodpłatnej pomocy prawnej przy poważnych sprawach.',q);src=[]}catch(e){}}
 lawc.push({r:'a',h:`${esc(ans)}${src.length?`<br><br><b>Podstawa:</b> ${src.map(esc).join('; ')}`:''}<br><br><span class="muted">To informacja prawna, nie porada w Twojej konkretnej sprawie.</span><div class="chips"><a class="chip" href="#/appeal">✍️ Przygotuj pismo</a><a class="chip" href="#/help">🧑‍⚖️ Porada z człowiekiem</a></div>`});drawLaw()}
const ACTS=[['Kodeks postępowania administracyjnego','Dz.U. 2025 poz. … (t.j.) – DEMO','obowiązujący'],['Ustawa o dostępie do informacji publicznej','Dz.U. … (t.j.) – DEMO','obowiązujący'],['Ustawa o petycjach','Dz.U. … (t.j.) – DEMO','obowiązujący'],['Ustawa o ochronie ludności i obronie cywilnej','Dz.U. 2024 – DEMO','obowiązujący'],['Kodeks wykroczeń','Dz.U. … (t.j.) – DEMO','obowiązujący']];
async function acts(){shell('📚 Baza aktów prawnych',`<div class="card"><label>Szukaj w Dzienniku Ustaw (tytuł)</label><div style="display:flex;gap:6px"><input id="aq" value="petycjach"><button class="chip" onclick="actSearch()">🔍</button></div></div><div id="aout"></div><p class="muted">Źródło: API ELI Kancelarii Sejmu (api.sejm.gov.pl/eli) – teksty jednolite i status obowiązywania.</p>`,{tab:'more'});actSearch()}
async function actSearch(){const q=$('#aq').value.trim(),o=$('#aout');o.innerHTML='<p class="muted">Szukam…</p>';
 try{const ctl=new AbortController();setTimeout(()=>ctl.abort(),6000);const r=await fetch('https://api.sejm.gov.pl/eli/acts/search?limit=8&title='+encodeURIComponent(q),{signal:ctl.signal});const j=await r.json();const it=(j.items||[]);if(!it.length)throw 0;
  o.innerHTML=card('Wyniki (na żywo)',it.map(a=>`<a class="row link" href="https://isap.sejm.gov.pl" target="_blank" rel="noopener"><span>${esc(a.title)}<br><span class="muted">${esc(a.publisher||'')} ${a.year||''} poz. ${a.pos||''} • ${esc(a.status||'')}</span></span><b>↗</b></a>`).join(''))}
 catch(e){const f=ACTS.filter(a=>a[0].toLowerCase().includes(q.toLowerCase().slice(0,6)));o.innerHTML=card('Wyniki (dane przykładowe – API niedostępne)',(f.length?f:ACTS).map(a=>`<div class="row"><span>${a[0]}<br><span class="muted">${a[1]}</span></span><b style="color:var(--ok)">${a[2]}</b></div>`).join(''))}}
const REG={krs:['KRS – spółki i fundacje','np. 0000123456 lub nazwa','EXAMPLE SP. Z O.O. (DEMO) • aktywna • zarząd: 2 osoby • kapitał 5 000 zł'],ceidg:['CEIDG – firmy jednoosobowe','NIP lub nazwa','Jan Przykładowy Usługi Remontowe (DEMO) • aktywna od 2019 • PKD 43.34.Z'],kw:['Księgi wieczyste','np. WA4M/00012345/6','Lokal mieszkalny 54 m² (DEMO) • dział III: brak wpisów • dział IV: hipoteka 320 000 zł'],cepik:['Historia pojazdu (CEPiK)','numer rejestracyjny + VIN','Toyota Corolla 2019 (DEMO) • 3 badania OK • przebieg rośnie • brak kradzieży'],biznes:['Biała lista VAT','NIP lub numer konta','Podatnik VAT czynny (DEMO) • rachunek na liście ✓'],bdo:['BDO / KRS NGO / rejestr dłużników (KRZ)','PESEL, NIP lub nazwa','Brak wpisów w Krajowym Rejestrze Zadłużonych (DEMO)']};
function registers(){shell('🗂️ Rejestry publiczne',`<p class="muted">Sprawdź kontrahenta, najemcę albo samochód przed zakupem – bez szukania po kilku portalach.</p>${Object.entries(REG).map(([k,[t,ph]])=>card(t,`<div style="display:flex;gap:6px"><input id="r_${k}" placeholder="${ph}"><button class="chip" onclick="$('#ro_${k}').innerHTML='<div class=\\'alert g\\'>✅<div>'+REG.${k}[2]+'</div></div>'">Sprawdź</button></div><div id="ro_${k}"></div>`)).join('')}<p class="muted">Wersja docelowa: KRS, CEIDG, EKW, CEPiK, wykaz podatników VAT i KRZ przez oficjalne API (dane przykładowe).</p>`,{tab:'more'})}

// ---------- WYJAŚNIJ PISMO ----------
function explain(){shell('📩 Wyjaśnij pismo',`<p class="muted">Wklej treść pisma albo zrób mu zdjęcie. Powiemy prostymi słowami, czego od Ciebie chcą, do kiedy i co możesz zrobić.</p><div class="chips"><label class="chip filechip">📷 Zdjęcie pisma<input type="file" accept="image/*" capture="environment" onchange="toast('DEMO: rozpoznawanie tekstu – wstawiono przykładową treść');$('#ex').value=EXSAMPLE"></label></div><textarea id="ex" rows="8">${EXSAMPLE}</textarea><button class="btn" onclick="explainGo()">Wyjaśnij po ludzku</button><div id="exo"></div>`,{tab:'more'})}
const EXSAMPLE='Na podstawie art. 104 Kodeksu postępowania administracyjnego Prezydent m.st. Warszawy orzeka o odmowie przyznania dodatku mieszkaniowego. Od niniejszej decyzji przysługuje odwołanie do Samorządowego Kolegium Odwoławczego w Warszawie za pośrednictwem organu, który wydał decyzję, w terminie 14 dni od dnia jej doręczenia.';
async function explainGo(){const t=$('#ex').value,l=t.toLowerCase(),o=$('#exo');const term=(l.match(/(\d+)\s*dni/)||[])[1];const typ=/odmow/.test(l)&&/decyzj/.test(l)?'Urząd odmówił Ci tego, o co prosiłeś/aś (decyzja odmowna).':/wezwani/.test(l)?'Urząd czegoś od Ciebie potrzebuje – wezwanie.':/nakaz zapłaty/.test(l)?'Sąd wydał nakaz zapłaty – jeśli się nie zgadzasz, musisz zareagować.':'To pismo urzędowe.';
 let plain=`${typ} ${/odwołani/.test(l)?'Możesz się odwołać – napiszesz, dlaczego się nie zgadzasz, a sprawę sprawdzi organ wyższego stopnia.':''}${term?` Masz na to ${term} dni od dnia, w którym dostałeś/aś pismo.`:''}`;
 if(S.llm.url||(window.aiOn&&aiOn())){try{plain=await llm('Wyjaśnij pismo urzędowe prostym językiem (poziom B1), w 3–4 zdaniach: co się stało, czego się od adresata oczekuje, jaki jest termin. Nie dodawaj informacji, których nie ma w piśmie.',t)}catch(e){}}
 o.innerHTML=`<div class="alert g">🗣️<div><b>Po ludzku:</b> ${esc(plain)}</div></div>${term?`<div class="card"><div class="row"><span>⏱️ Termin w piśmie</span><b>${term} dni od doręczenia</b></div><a class="btn sec small" href="#/deadline">Policz dokładną datę</a></div>`:''}<div class="chips">${/odwołani/.test(l)?'<a class="chip" href="#/appeal/odwolanie">✍️ Napisz odwołanie</a>':''}<a class="chip" href="#/help">🧑‍⚖️ Porada z człowiekiem</a><button class="chip" onclick="speak($('#exo').innerText)">🔊 Przeczytaj</button></div>`}

// ---------- BUDOWA ----------
F.budowa={t:'Budowa domu – pozwolenie lub zgłoszenie',i:'🏗️',steps:[
 {h:'Co budujesz?',b:`<label>Rodzaj inwestycji</label><select name="rodz"><option>Dom jednorodzinny do 70 m² (zgłoszenie)</option><option>Dom jednorodzinny – pełne pozwolenie na budowę</option><option>Garaż / wiata do 35 m² (zgłoszenie)</option><option>Rozbudowa / nadbudowa</option></select><label>Działka</label><input name="dz" value="146518_8.0101.12/4 (Piaseczno – DEMO)"><div class="alert g">🗺️<div>Miejscowy plan (Geoportal – DEMO): <b>MN – zabudowa mieszkaniowa jednorodzinna</b>, wys. do 9 m, pow. biologicznie czynna min. 50%. Twoja inwestycja jest zgodna.</div></div>`},
 {h:'Dokumenty',b:`<label class="chk"><input type="checkbox" name="proj" checked> Projekt zagospodarowania działki i architektoniczno-budowlany (PDF, podpis projektanta)</label><label class="chk"><input type="checkbox" name="osw" checked> Oświadczenie o prawie do dysponowania nieruchomością (wypełnione z księgi wieczystej)</label><label class="chk"><input type="checkbox" name="media"> Warunki przyłączenia mediów</label><label>Organ</label><select name="org"><option>Starosta Piaseczyński (DEMO)</option></select>`}],
 sum:f=>[['Inwestycja',f.rodz],['Działka',f.dz],['Projekt',f.proj?'dołączony':'brak'],['Organ',f.org],['Ścieżka','e-Budownictwo (GUNB)']],
 done:()=>'Wniosek złożony w systemie e-Budownictwo (DEMO). Organ może wnieść sprzeciw lub wydać decyzję – status i pisma zobaczysz w skrzynce. Rozpoczęcie budowy zgłosisz tu jednym kliknięciem.'};

// ---------- ENERGIA ----------
function energy(){shell('⚡ Prąd i taryfa',`<div class="card"><h3>Twój licznik (DEMO)</h3><div class="row"><span>Sprzedawca</span><b>PGE Obrót (DEMO)</b></div><div class="row"><span>Taryfa</span><b>G11</b></div><div class="row"><span>Zużycie roczne</span><b><input id="ekwh" type="number" value="2400" style="width:90px;padding:4px"> kWh</b></div><label>Ile prądu zużywasz w nocy i w weekendy?</label><input id="enoc" type="range" min="10" max="70" value="40" oninput="$('#enl').textContent=this.value+'%';calcE()"><p class="muted">Noc/weekend: <b id="enl">40%</b></p></div><div id="eout"></div>
 <p class="muted">Ceny przykładowe (DEMO). Wersja docelowa: dane z licznika przez Centralny System Informacji Rynku Energii i oferty z porównywarki URE. Zmiana sprzedawcy jest bezpłatna i nie wymaga wymiany licznika.</p>`,{tab:'more'});$('#ekwh').oninput=calcE;calcE()}
function calcE(){const k=+$('#ekwh').value||0,n=+$('#enoc').value/100;const g11=k*1.15+12*25,g12=k*(n*0.72+(1-n)*1.30)+12*29;const best=g12<g11?'G12':'G11';
 $('#eout').innerHTML=card('Porównanie (rocznie)',`<div class="row"><span>G11 – jedna cena</span><b>${Math.round(g11)} zł</b></div><div class="row"><span>G12 – tańsza noc i weekend</span><b>${Math.round(g12)} zł</b></div><div class="alert ${best=='G12'?'g':'b'}">${best=='G12'?'💡':'✅'}<div>${best=='G12'?`Taryfa G12 obniży rachunek o ok. <b>${Math.round(g11-g12)} zł rocznie</b>.`:'Przy Twoim zużyciu G11 jest korzystniejsza – nic nie zmieniaj.'}</div></div>${best=='G12'?`<button class="btn" onclick="eidSign('Zmiana taryfy na G12 (DEMO)',()=>{S.cases.push({t:'Zmiana taryfy na G12',no:caseNo(),st:'Złożono'});save();toast('Wniosek do sprzedawcy wysłany ✅ (DEMO)')})">Zmień taryfę na G12</button>`:''}<a class="btn ghost small" href="https://www.ure.gov.pl" target="_blank" rel="noopener">Porównywarka ofert URE ↗</a>`)}

// ---------- PODRÓŻE ----------
function travel(){const t=S.v4.tickets;shell('🚆 Podróże',`${card('🚆 Bilet PKP',`<label>Skąd</label><input id="tf" value="Warszawa Centralna"><label>Dokąd</label><input id="tt" value="Kraków Główny"><label>Kiedy</label><input id="td2" type="datetime-local" value="2026-10-30T07:00"><label>Ulga</label><select id="tu"><option>Normalny</option><option>Studencka 51%</option><option>Karta Dużej Rodziny 37%</option><option>Senior 60+ (oferta przewoźnika)</option></select><button class="btn" onclick="trainSearch()">Szukaj połączeń</button><div id="tout2"></div>`)}
 ${t.length?card('🎫 Moje bilety',t.map(x=>`<div class="row"><span>${esc(x.r)}<br><span class="muted">${x.d} • wagon 7, miejsce ${x.m}</span></span>${qrSVG(x.r).replace('class="qr"','class="qr mini"')}</div>`).join('')):''}
 ${card('✈️ Lot za granicę',`${rowl('🛂','Czy mój dokument wystarczy?','#/wallet','paszport ważny do 30.06.2028')+rowl('🌍','Polak za granicą – ostrzeżenia MSZ i rejestracja podróży (Odyseusz)','#/travel')+rowl('🏥','EKUZ – leczenie w UE','#/doc/ekuz')}<p class="muted">Bilety lotnicze kupujesz u przewoźnika – aplikacja publiczna nie pośredniczy w sprzedaży komercyjnej, ale podpowie, czego potrzebujesz.</p>`)}`,{tab:'more'})}
function trainSearch(){const f=$('#tf').value,t=$('#tt').value,u=$('#tu').value;const disc=/51/.test(u)?.49:/37/.test(u)?.63:/60/.test(u)?.7:1;const L=[['07:05','09:28','EIC 1300',169],['08:05','10:29','IC 3500',89],['09:05','11:20','EIP 1504',189]];
 $('#tout2').innerHTML=L.map(([a,b,n,p],i)=>`<div class="row"><span><b>${a} → ${b}</b><br><span class="muted">${n}</span></span><button class="chip" data-r="${esc(f+' → '+t+', '+n+' '+a)}" data-p="${(p*disc).toFixed(2)}" onclick="buyTrain(this.dataset.r,this.dataset.p)">${(p*disc).toFixed(2)} zł</button></div>`).join('')+'<p class="muted">Rozkład i ceny przykładowe (DEMO).</p>'}
function buyTrain(r,p){const m=modal(`<h3>Kup bilet</h3><p>${esc(r)}</p><div class="row"><span>Cena</span><b>${p} zł</b></div><div class="row"><span>Płatność</span><b>${S.v4.card?'Karta •••• '+S.v4.card:'BLIK'}</b></div><p class="muted">Dokument uprawniający do ulgi sprawdzimy automatycznie w mObywatelu.</p><button class="btn" id="tb">Zapłać i pobierz bilet</button><button class="btn ghost" onclick="closeModal()">Anuluj</button>`);m.querySelector('#tb').onclick=()=>{closeModal();S.v4.tickets.push({r,d:new Date($('#td2')?.value||Date.now()).toLocaleString('pl-PL'),m:20+Math.floor(Math.random()*60)});save();travel();toast('Bilet kupiony ✅ (DEMO)')}}

// ---------- AGENT SPRAW ----------
const AG={przeprowadzka:{t:'Przeprowadzam się do Krakowa',s:[['Meldunek na nowy adres','#/flow/meldunek'],['Zmiana adresu w dowodzie rejestracyjnym (CEPiK)',null],['Aktualizacja adresu w US i ZUS',null],['Deklaracja śmieciowa w Krakowie',null],['Wybór nowej przychodni POZ (deklaracja)',null],['Zapis dzieci do szkoły i przedszkola w rejonie',null],['Przepisanie umowy na prąd (licznik – odczyt)','#/energy']]},
 smierc:{t:'Zmarła bliska osoba',s:[['Akt zgonu – odbiór w USC (wydany elektronicznie)',null],['Zasiłek pogrzebowy z ZUS',null],['Wstrzymanie świadczeń zmarłego',null],['Informacja o rachunkach zmarłego (Centralna Informacja o Rachunkach)',null],['Spadek: przypomnienie o 6 miesiącach na decyzję','#/lawai'],['Wyrejestrowanie lub przerejestrowanie pojazdu',null]]},
 firma:{t:'Zakładam jednoosobową firmę',s:[['Wpis do CEIDG (NIP, REGON)',null],['Wybór formy opodatkowania',null],['Zgłoszenie do ZUS – ulga na start',null],['Rachunek firmowy na białej liście VAT','#/registers'],['Adres do e-Doręczeń dla firmy','#/inbox']]},
 auto:{t:'Sprzedaję samochód',s:[['Umowa sprzedaży podpisana w aplikacji przez obie strony',null],['Zgłoszenie zbycia pojazdu (30 dni)',null],['Powiadomienie ubezpieczyciela OC',null],['Wydanie kluczy i dokumentów – checklista',null]]}};
function agent(k){const a=AG[k];if(!a){shell('🧩 Agent spraw',`<div class="alert b">🧩<div><b>Powiedz, co się dzieje w Twoim życiu – agent rozpisze wszystkie sprawy i załatwi je po kolei.</b> Każdy krok widzisz i zatwierdzasz. Agent nigdy nie płaci i nie podpisuje bez Ciebie.</div></div>${Object.entries(AG).map(([x,v])=>rowl('▶',v.t,'#/agent/'+x,v.s.length+' spraw')).join('')}<div class="card"><label>Albo opisz własnymi słowami</label><input id="agq" placeholder="np. urodziło mi się dziecko i przeprowadzam się"><button class="btn sec" onclick="const q=$('#agq').value.toLowerCase();location.hash='#/agent/'+(/przeprow|kraków|adres/.test(q)?'przeprowadzka':/zmarł|śmier|pogrzeb/.test(q)?'smierc':/firm|działalno/.test(q)?'firma':/sprzeda|auto/.test(q)?'auto':'przeprowadzka')">Ułóż plan</button></div>`,{tab:'more'});return}
 const st=S.v4.agent[k]||(S.v4.agent[k]=a.s.map(()=>0));const done=st.filter(x=>x==2).length;
 shell('🧩 '+a.t,`<div class="card"><h3>Plan: ${done}/${a.s.length} gotowe</h3><div class="bar"><i style="width:${done/a.s.length*100}%"></i></div></div>${a.s.map(([t,h],i)=>`<div class="card agstep ${['','run','ok'][st[i]]}"><div class="row"><span>${['⬜','⏳','✅'][st[i]]} ${t}</span>${st[i]==2?'<b style="color:var(--ok)">gotowe</b>':h?`<a class="chip" href="${h}">Zrób ze mną</a>`:`<button class="chip" onclick="agRun('${k}',${i})">Zatwierdź</button>`}</div></div>`).join('')}${done<a.s.length?`<button class="btn" onclick="agAll('${k}')">Zatwierdź wszystkie automatyczne kroki</button>`:'<div class="alert g">🎉<div>Wszystko załatwione. Potwierdzenia masz w skrzynce.</div></div>'}<p class="muted">Kroki oznaczone „Zrób ze mną” wymagają Twoich decyzji. Pozostałe agent wypełnia danymi z rejestrów i wysyła po jednym podpisie.</p>`,{tab:'more'})}
function agRun(k,i){S.v4.agent[k][i]=1;agent(k);setTimeout(()=>{S.v4.agent[k][i]=2;save();if(location.hash=='#/agent/'+k)agent(k)},900)}
function agAll(k){eidSign('Pakiet spraw: '+AG[k].t,()=>{AG[k].s.forEach(([t,h],i)=>{if(!h&&S.v4.agent[k][i]!=2)S.v4.agent[k][i]=1});agent(k);let d=0;AG[k].s.forEach(([t,h],i)=>{if(S.v4.agent[k][i]==1){setTimeout(()=>{S.v4.agent[k][i]=2;save();if(location.hash=='#/agent/'+k)agent(k)},600*(++d))}});S.cases.push({t:'Agent: '+AG[k].t,no:caseNo(),st:'W toku'});save()})}

// ---------- POMOC CYFROWA ----------
const TECH=[['📶','Podłącz telefon do Wi-Fi',['Otwórz Ustawienia.','Wybierz „Wi-Fi” i włącz przełącznik.','Dotknij nazwy swojej sieci (jest na naklejce routera).','Wpisz hasło z naklejki – wielkość liter ma znaczenie.','Gotowe, gdy przy nazwie pojawi się „Połączono”.']],['🔐','Zabezpiecz konta (weryfikacja dwuetapowa)',['Zaloguj się do poczty i banku.','Wejdź w „Bezpieczeństwo”.','Włącz weryfikację dwuetapową (aplikacja lub SMS).','Zapisz kody zapasowe na kartce i schowaj.']],['👵','Ustaw telefon seniorowi',['Powiększ czcionkę: Ustawienia → Wyświetlacz → Rozmiar tekstu.','Dodaj ulubione kontakty na ekran główny.','Włącz numer alarmowy i kartę ICE na ekranie blokady.','Włącz w mObywatelu tryb seniora i zaufaną osobę.']],['💾','Kopia zapasowa zdjęć i kontaktów',['Ustawienia → Konto → Kopia zapasowa.','Włącz kopię zdjęć i kontaktów.','Sprawdź, czy jest miejsce w chmurze lub podłącz dysk.']],['🖨️','Drukarka / komputer nie łączy się z siecią',['Uruchom ponownie router (odłącz na 30 s).','Uruchom ponownie urządzenie.','Sprawdź, czy jest w tej samej sieci Wi-Fi.','Nadal nie działa? Umów pomoc wolontariusza.']]];
function tech(i){if(i!==undefined&&TECH[i]){const t=TECH[i];shell(t[0]+' '+t[1],`<div class="card">${t[2].map((s,j)=>`<label class="chk"><input type="checkbox"> <span><b>${j+1}.</b> ${s}</span></label>`).join('')}</div><button class="btn ghost" onclick="speak(${JSON.stringify(t[2].join(' ')).replace(/"/g,'&quot;')})">🔊 Przeczytaj kroki</button><a class="btn sec" href="#/tech">Wróć</a>`);return}
 shell('🛠️ Pomoc cyfrowa',`<div class="alert r">⚠️<div><b>Urząd nigdy nie zadzwoni z prośbą o zainstalowanie programu do zdalnej pomocy</b> (AnyDesk, TeamViewer) ani o kod BLIK. To oszustwo – <a href="#/phishing">sprawdź</a>.</div></div>${TECH.map((t,j)=>rowl(t[0],t[1],'#/tech/'+j)).join('')}
 ${card('🙋 Pomoc człowieka',`<p class="muted">Bezpłatna pomoc wolontariusza w bibliotece lub domu kultury – albo zdalnie, ale tylko gdy to <b>Ty</b> podasz jednorazowy kod z tej aplikacji.</p><button class="btn sec" onclick="eidSign('Umówienie pomocy cyfrowej – Biblioteka Mokotów, śr 28.10, 12:00 (DEMO)',()=>toast('Umówiono ✅ (DEMO)'))">Umów: śr 28.10, 12:00 – Biblioteka Mokotów</button><button class="btn ghost" onclick="const c=Math.floor(100000+Math.random()*9e5);modal('<h3>Twój kod pomocy: '+c+'</h3><p class=muted>Podaj go tylko wolontariuszowi, z którym jesteś umówiony/a w aplikacji. Kod wygasa za 10 minut, a sesję przerwiesz w każdej chwili.</p><button class=btn onclick=closeModal()>OK</button>')">Wygeneruj kod zdalnej pomocy</button>`)}`,{tab:'more'})}

// ---------- OPIEKA SPOŁECZNA ----------
function social(){shell('🤝 Pomoc społeczna',`<div class="alert b">🤝<div>Sprawdź orientacyjnie, czy przysługuje Ci pomoc, i złóż wniosek do ośrodka pomocy społecznej. <b>O przyznaniu decyduje pracownik socjalny</b>, nie algorytm.</div></div>
 <div class="card"><h3>Kalkulator kryterium dochodowego</h3><label>Liczba osób w gospodarstwie</label><input id="so" type="number" min="1" value="1"><label>Łączny dochód netto miesięcznie (zł)</label><input id="sd" type="number" value="950"><button class="btn sec" onclick="calcSoc()">Sprawdź orientacyjnie</button><div id="sout"></div></div>
 ${card('Wnioski',['Zasiłek celowy (np. leki, opał)','Zasiłek okresowy','Usługi opiekuńcze w domu','Asystent rodziny','Posiłek w szkole dla dziecka','Opieka wytchnieniowa dla opiekuna osoby z niepełnosprawnością'].map(x=>`<div class="row"><span>${x}</span><button class="chip" onclick="eidSign('Wniosek: ${x} – MOPS Mokotów',()=>{S.cases.push({t:'${x}',no:caseNo(),st:'Złożono'});save();toast('Wniosek złożony ✅ Pracownik socjalny umówi wywiad (DEMO)')})">Złóż</button></div>`).join(''))}
 ${card('💬 Kontakt z pracownikiem socjalnym',`<p class="muted">Napisz albo poproś o telefon – także w imieniu sąsiada, który potrzebuje pomocy.</p><button class="btn ghost" onclick="toast('Prośba o kontakt wysłana do OPS Mokotów (DEMO)')">Poproś o kontakt</button>`)}`,{tab:'more'})}
function calcSoc(){const o=Math.max(1,+$('#so').value),d=+$('#sd').value;const kr=o==1?1010:823*o;$('#sout').innerHTML=`<div class="alert ${d<=kr?'g':'y'}">${d<=kr?'✅':'ℹ️'}<div>Kryterium dla Twojego gospodarstwa: <b>${kr} zł</b> (DEMO – wartości przykładowe, sprawdź aktualne). ${d<=kr?'Dochód mieści się w kryterium – złóż wniosek.':'Dochód przekracza kryterium, ale zasiłek celowy specjalny lub usługi mogą być przyznane także wtedy – zapytaj pracownika socjalnego.'}</div></div>`}

